do $patch_v5_guided_step_visual_stimulus$
declare
  function_definition text;
  old_clause text := '''position'', item.position';
  new_clause text := '''position'', item.position, ''visual_stimulus'', question.metadata->''visual_stimulus''';
  occurrence_count integer;
begin
  select pg_get_functiondef('public.get_guided_learning_step_v4(uuid)'::regprocedure)
    into function_definition;
  if function_definition is null then raise exception 'V5_VISUAL_STEP_FUNCTION_MISSING'; end if;
  if position(new_clause in function_definition) > 0 then return; end if;
  select (length(function_definition)-length(replace(function_definition, old_clause, '')))/length(old_clause)
    into occurrence_count;
  if occurrence_count <> 1 then raise exception 'V5_VISUAL_STEP_PATCH_MISMATCH'; end if;
  execute replace(function_definition, old_clause, new_clause);
end;
$patch_v5_guided_step_visual_stimulus$;


-- Authorial V5 content is compiled for review but remains inactive and unaligned.
-- No student can receive it until separate pedagogical and publication gates pass.
do $seed_question_first_content_v5$
declare
  v_catalog_id uuid;
  v_skill_id uuid;
  v_lesson_id uuid;
  v_set_id uuid;
  v_question_id uuid;
  v_question record;
begin
  select id into v_catalog_id
    from public.learning_curriculum_catalogs
   where code = 'TECESCOLA_CORE' and version = '1.0'
   limit 1;
  if v_catalog_id is null then raise exception 'V5_CONTENT_CATALOG_MISSING'; end if;
  select id into v_skill_id
    from public.learning_curriculum_skills
   where catalog_id = v_catalog_id and code = 'ART_COMPARE_COMPOSITIONS';
  if v_skill_id is null then raise exception 'V5_CONTENT_SKILL_MISSING'; end if;

  insert into public.learning_skill_lessons(
    canonical_skill_id, version, title, summary, content_markdown,
    worked_example, tips, estimated_minutes, active, metadata
  ) values (
    v_skill_id, 11, 'Comparar escolhas de composição com evidências', 'Observe elementos, relações e efeitos possíveis. Uma boa leitura distingue o que está visível, o que pode ser interpretado e o que exigiria contexto adicional.', '## Comece pelo que está presente
Identifique linhas, formas, cores, texturas, luz, escala, posição e enquadramento. Nomear um elemento é uma observação; ainda não explica o papel que ele desempenha.

## Observe relações
Compare figura e fundo, proximidade, repetição, direção, tamanho e contraste. Hierarquia visual descreve como algumas partes ganham destaque em relação a outras. Ela não prova, sozinha, o que o público sentirá.

## Sustente interpretações
Relacione uma escolha formal a um efeito possível e aponte a evidência. Separe descrição, interpretação e contexto. Cor ou forma não possui significado universal independente da obra, da situação e de quem a lê.

## Compare com critérios consistentes
Use os mesmos critérios para as duas composições. Pergunte o que mudou, o que permaneceu e como essas relações alteram a leitura. Uma descrição acessível pode comunicar evidências visuais; quando a tarefa pede observação direta de uma obra, a imagem precisa estar disponível e ter texto alternativo.',
    'Em dois cartazes para o mesmo evento, a chamada do primeiro aparece em letras escuras sobre um bloco amarelo e ocupa mais espaço; no segundo, letras cinza-claro ficam diretamente sobre fundo branco e os detalhes têm tamanho semelhante. A comparação sustentada é que o primeiro separa mais a chamada do fundo e cria uma hierarquia mais nítida. Não se pode concluir que amarelo sempre significa urgência, nem que todas as pessoas reagirão da mesma maneira.', array['Anote primeiro o elemento visível e sua relação espacial.', 'Use critérios iguais ao comparar duas obras.', 'Qualifique efeitos como possibilidades e não como reações universais.']::text[], 12, false, '{"content_pack":"TECESCOLA_CORE_V5_QUESTION_FIRST","content_id":"v11-art-compare-compositions-visual-evidence","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","publication_status":"STAGING","bncc_alignment_status":"NOT_CLAIMED","prior_knowledge":["Reconhecer cor, linha, forma e posição em uma composição."],"key_concepts":["Contraste","figura e fundo","hierarquia visual","ritmo","enquadramento","observação e interpretação"],"progression":[],"micro_explanations":[{"id":"art-elements","title":"Elementos","content":"Cor, linha, forma, escala e posição são elementos que podem ser descritos antes de interpretar."},{"id":"art-relations","title":"Relações","content":"Contraste e hierarquia dependem da relação entre elementos, não de um item isolado."},{"id":"art-evidence","title":"Evidências","content":"A interpretação fica mais clara quando aponta a característica visual que a sustenta."}],"remediations":[{"id":"art-observe","trigger":"Atribui significado universal à cor ou forma.","action":"Reescreva a resposta como duas partes: “vejo...” e “isso pode produzir...”. Marque qual parte é observação e qual é interpretação."},{"id":"art-compare","trigger":"Compara obras usando critérios diferentes.","action":"Monte uma tabela com os mesmos critérios para ambas: contraste, escala, posição e repetição. Só então descreva semelhanças e diferenças."}],"source_dossier":[{"publisher":"J. Paul Getty Museum, Education","title":"Understanding Formal Analysis","url":"https://www.getty.edu/education/teachers/classroom_resources/formal_analysis.html","license":"Referência pedagógica consultada; conteúdo e cartazes deste pacote são autorais e não reproduzem obras do Getty."},{"publisher":"Ministério da Educação, Brasil","title":"Base Nacional Comum Curricular","url":"https://basenacionalcomum.mec.gov.br/images/BNCC_EI_EF_110518_versaofinal_site.pdf","license":"Referência curricular consultada; vínculo oficial específico não reivindicado neste pacote."}],"copyright_note":"Questões e dois cartazes foram criados para este pacote. Nenhuma imagem de terceiros foi incorporada. Revisão pedagógica pendente; sem reivindicação de alinhamento oficial. Lote V11 autoral com 100 questões e revisão pedagógica pendente; publicação mantida em STAGING.","authentic_activities":[{"id":"art-poster-evidence-annotation","title":"Anotar evidências de composição","objective":"Comparar escolhas formais e justificar uma leitura visual usando evidências dos dois cartazes.","instructions":"Observe os dois cartazes autorais. Em uma folha ou arquivo acessível, identifique a chamada principal, compare contraste, escala e posição dos detalhes e justifique qual informação tende a ser percebida primeiro. Depois, proponha uma alteração em um dos cartazes e explique qual relação visual ela mudaria. É permitido responder por texto, áudio ou anotação ampliada.","evidence":"Anotação que distingue descrição de interpretação, usa pelo menos duas evidências visuais e justifica uma alteração proposta.","privacyGuard":"Use somente os cartazes fictícios deste pacote. Não envie imagens de estudantes, dados pessoais ou fotografias de pessoas identificáveis.","rubric":[{"criterion":"Evidência visual","emerging":"Nomeia um elemento sem relacioná-lo ao efeito.","developing":"Relaciona um elemento a um possível destaque.","proficient":"Compara ao menos duas relações visuais e sustenta a leitura com evidências dos dois cartazes."},{"criterion":"Revisão compositiva","emerging":"Sugere mudança sem indicar o que ela altera.","developing":"Indica um elemento a alterar e um efeito possível.","proficient":"Propõe alteração coerente e explica como contraste, escala ou posição mudaria a hierarquia."}]}],"source_question_feedback":[{"questionId":"v3-art-art_interpretation-1","hint":"Localize no enunciado uma escolha formal descrita (cor, linha, forma, escala, ritmo ou enquadramento). Diferencie essa observação de uma hipótese sobre intenção, qualidade ou reação do público.","errorFocus":"VISUAL_EVIDENCE_BEFORE_INFERENCE"},{"questionId":"v3-art-art_interpretation-6","hint":"Localize no enunciado uma escolha formal descrita (cor, linha, forma, escala, ritmo ou enquadramento). Diferencie essa observação de uma hipótese sobre intenção, qualidade ou reação do público.","errorFocus":"VISUAL_EVIDENCE_BEFORE_INFERENCE"},{"questionId":"v3-art-art_interpretation-10","hint":"Localize no enunciado uma escolha formal descrita (cor, linha, forma, escala, ritmo ou enquadramento). Diferencie essa observação de uma hipótese sobre intenção, qualidade ou reação do público.","errorFocus":"VISUAL_EVIDENCE_BEFORE_INFERENCE"},{"questionId":"v4-authored-art-art_compare_compositions-probe-01","hint":"Localize no enunciado uma escolha formal descrita (cor, linha, forma, escala, ritmo ou enquadramento). Diferencie essa observação de uma hipótese sobre intenção, qualidade ou reação do público.","errorFocus":"VISUAL_EVIDENCE_BEFORE_INFERENCE"},{"questionId":"v4-authored-art-art_compare_compositions-probe-02","hint":"Localize no enunciado uma escolha formal descrita (cor, linha, forma, escala, ritmo ou enquadramento). Diferencie essa observação de uma hipótese sobre intenção, qualidade ou reação do público.","errorFocus":"VISUAL_EVIDENCE_BEFORE_INFERENCE"},{"questionId":"v4-authored-art-art_compare_compositions-practice-03","hint":"Localize no enunciado uma escolha formal descrita (cor, linha, forma, escala, ritmo ou enquadramento). Diferencie essa observação de uma hipótese sobre intenção, qualidade ou reação do público.","errorFocus":"VISUAL_EVIDENCE_BEFORE_INFERENCE"},{"questionId":"v4-authored-art-art_compare_compositions-practice-04","hint":"Localize no enunciado uma escolha formal descrita (cor, linha, forma, escala, ritmo ou enquadramento). Diferencie essa observação de uma hipótese sobre intenção, qualidade ou reação do público.","errorFocus":"VISUAL_EVIDENCE_BEFORE_INFERENCE"},{"questionId":"v4-authored-art-art_compare_compositions-transfer-05","hint":"Localize no enunciado uma escolha formal descrita (cor, linha, forma, escala, ritmo ou enquadramento). Diferencie essa observação de uma hipótese sobre intenção, qualidade ou reação do público.","errorFocus":"VISUAL_EVIDENCE_BEFORE_INFERENCE"},{"questionId":"v4-authored-art-art_compare_compositions-lock_in-06","hint":"Localize no enunciado uma escolha formal descrita (cor, linha, forma, escala, ritmo ou enquadramento). Diferencie essa observação de uma hipótese sobre intenção, qualidade ou reação do público.","errorFocus":"VISUAL_EVIDENCE_BEFORE_INFERENCE"},{"questionId":"v4-authored-art-art_compare_compositions-review-07","hint":"Localize no enunciado uma escolha formal descrita (cor, linha, forma, escala, ritmo ou enquadramento). Diferencie essa observação de uma hipótese sobre intenção, qualidade ou reação do público.","errorFocus":"VISUAL_EVIDENCE_BEFORE_INFERENCE"},{"questionId":"v4-authored-art-art_compare_compositions-review-08","hint":"Localize no enunciado uma escolha formal descrita (cor, linha, forma, escala, ritmo ou enquadramento). Diferencie essa observação de uma hipótese sobre intenção, qualidade ou reação do público.","errorFocus":"VISUAL_EVIDENCE_BEFORE_INFERENCE"}],"objective":"Descrever relações entre elementos visuais e sustentar uma comparação sem atribuir significados universais ou intenções não demonstradas.","common_mistake":"Inferir uma emoção, intenção ou qualidade universal a partir de uma cor isolada, sem considerar relações visuais e contexto.","estimated_minutes":12}'::jsonb
  ) on conflict (canonical_skill_id, version) do nothing;
  select id into v_lesson_id from public.learning_skill_lessons
   where canonical_skill_id = v_skill_id and version = 11
     and metadata->>'content_id' = 'v11-art-compare-compositions-visual-evidence' and active = false;
  if v_lesson_id is null then raise exception 'V5_CONTENT_LESSON_CONFLICT'; end if;

  for v_question in
    select * from jsonb_to_recordset('[{"id":"v5-art-compare-compositions-probe-01","purpose":"PROBE","difficulty":"EASY","cognitiveProcess":"IDENTIFY","contextFamily":"MURAL_ESCOLAR","statement":"Em um mural escolar fictício, linhas diagonais partem dos cantos e convergem para uma janela iluminada. Que efeito compositivo essa organização tende a produzir?","options":["As linhas conduzem o olhar em direção à janela.","As linhas provam a intenção pessoal de quem pintou o mural.","A janela deixa de fazer parte da composição.","As diagonais garantem que todas as pessoas sintam a mesma emoção."],"correctAnswer":"As linhas conduzem o olhar em direção à janela.","explanation":"A direção das linhas pode orientar o percurso do olhar. O enunciado não permite afirmar a intenção ou a reação de todas as pessoas.","hint":"Observe para onde as linhas apontam antes de atribuir intenção ou emoção.","errorFocus":"DIRECTIONAL_LINES","misconceptions":{"As linhas provam a intenção pessoal de quem pintou o mural.":["LINES_AS_PROOF_OF_INTENTION"]},"position":1},{"id":"v5-art-compare-compositions-probe-02","purpose":"PROBE","difficulty":"EASY","cognitiveProcess":"DISTINGUISH","contextFamily":"FORMAS_ADJACENTES","statement":"Uma composição autoral coloca formas azuis e laranjas de tamanhos iguais lado a lado. Qual descrição se apoia diretamente no que foi informado?","options":["O azul representa tristeza para todas as pessoas.","As cores são diferentes e aparecem em formas de tamanho igual.","O laranja é necessariamente a cor mais importante.","A composição foi criada para uma ocasião histórica específica."],"correctAnswer":"As cores são diferentes e aparecem em formas de tamanho igual.","explanation":"A descrição informa diferença de cor e igualdade de tamanho. Sentidos universais ou contexto histórico exigiriam outras evidências.","hint":"Separe o que foi descrito de interpretações que dependeriam de contexto adicional.","errorFocus":"OBSERVATION_BEFORE_MEANING","misconceptions":{"O azul representa tristeza para todas as pessoas.":["COLOR_AS_UNIVERSAL_MEANING"]},"position":2},{"id":"v5-art-compare-compositions-practice-01","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"ANALYZE","contextFamily":"ENQUADRAMENTO_FOTOGRAFICO","statement":"Uma série fotográfica mostra uma praça primeiro em plano amplo, com pessoas e edifícios, e depois em enquadramento fechado nas mãos de duas pessoas trocando sementes. O que a mudança de enquadramento permite comparar?","options":["A intenção biográfica de quem fotografou.","A quantidade exata de pessoas presentes fora do enquadramento.","O contexto coletivo da praça e o gesto específico da troca.","Que a segunda fotografia é mais verdadeira que a primeira."],"correctAnswer":"O contexto coletivo da praça e o gesto específico da troca.","explanation":"O plano amplo inclui relações com o espaço; o fechado destaca um gesto. O enquadramento muda quais elementos ficam visíveis, sem provar intenção ou totalidade.","hint":"Compare quais informações entram e saem do campo em cada enquadramento.","errorFocus":"FRAMING_AND_SCOPE","misconceptions":{"A intenção biográfica de quem fotografou.":["CROP_AS_COMPLETE_SCENE"]},"position":1},{"id":"v5-art-compare-compositions-practice-02","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"ANALYZE","contextFamily":"RITMO_EM_PADRAO","statement":"Em uma gravura autoral, pequenos círculos se repetem em intervalos regulares; perto da borda, os intervalos diminuem. Qual leitura descreve melhor essa mudança?","options":["A repetição prova que a gravura foi feita por uma máquina.","Os círculos deixam de ter relação porque mudam de intervalo.","A borda indica necessariamente o início de uma narrativa.","A repetição cria ritmo, e a redução dos intervalos altera sua cadência perto da borda."],"correctAnswer":"A repetição cria ritmo, e a redução dos intervalos altera sua cadência perto da borda.","explanation":"A repetição e a variação dos intervalos são evidências para descrever ritmo. A técnica e a narrativa não podem ser concluídas apenas por esses dados.","hint":"Observe o padrão e a mudança dos intervalos sem deduzir uma técnica específica.","errorFocus":"REPETITION_AND_VARIATION","misconceptions":{"A repetição prova que a gravura foi feita por uma máquina.":["REPETITION_AS_PROOF_OF_MEDIUM"]},"position":2},{"id":"v5-art-compare-compositions-transfer-contrast-05-v2","purpose":"TRANSFER","difficulty":"MEDIUM","cognitiveProcess":"COMPARE","contextFamily":"CARTAZES_AUTORAIS","statement":"Observe os dois cartazes autorais da mesma campanha. Qual comparação relaciona melhor contraste e hierarquia às diferenças visíveis?","options":["O cartaz A separa melhor a chamada do fundo e a organiza como informação principal; no B, o baixo contraste e o peso semelhante dos elementos reduzem essa hierarquia.","O cartaz B destaca mais a chamada porque seus elementos secundários têm peso visual próximo.","Os cartazes têm a mesma composição porque anunciam o mesmo evento.","O cartaz A prova que cores amarelas sempre tornam uma mensagem mais importante."],"correctAnswer":"O cartaz A separa melhor a chamada do fundo e a organiza como informação principal; no B, o baixo contraste e o peso semelhante dos elementos reduzem essa hierarquia.","explanation":"No cartaz A, a chamada escura sobre o bloco amarelo tem maior contraste e escala, enquanto os detalhes aparecem abaixo. No B, o texto claro sobre branco e os pesos próximos reduzem a separação. Isso sustenta a comparação sem transformar uma cor em significado universal.","hint":"Compare relação figura-fundo, tamanho da chamada e peso dos elementos secundários.","errorFocus":"CONTRAST_AND_HIERARCHY","misconceptions":{"O cartaz B destaca mais a chamada porque seus elementos secundários têm peso visual próximo.":["SAME_MESSAGE_AS_SAME_COMPOSITION"]},"visualStimulus":{"layout":"TWO_COLUMN","items":[{"src":"/learning/art/poster-contrast-a.svg","alt":"Cartaz A: chamada “Feira de trocas do bairro” em letras azul-marinho, grande, sobre um bloco amarelo; as informações de data e local aparecem menores abaixo.","caption":"Cartaz A"},{"src":"/learning/art/poster-contrast-b.svg","alt":"Cartaz B: a mesma chamada em letras cinza-claro diretamente sobre fundo branco; os detalhes têm tamanho e peso visual próximos aos da chamada.","caption":"Cartaz B"}]},"position":1},{"id":"v5-art-compare-compositions-transfer-02","purpose":"TRANSFER","difficulty":"HARD","cognitiveProcess":"EVALUATE","contextFamily":"SINALIZACAO_DE_EXPOSICAO","statement":"Em uma exposição fictícia, uma placa reúne título, horário e uma seta. A seta aponta para a sala seguinte, enquanto o título usa letras maiores que os demais textos. Qual avaliação usa evidências sem extrapolar?","options":["A placa prova que visitantes sempre seguirão a seta.","O tamanho diferencia o título, e a direção da seta orienta o percurso indicado pela placa.","O título maior revela a intenção íntima de quem organizou a exposição.","A seta torna desnecessárias as informações de horário."],"correctAnswer":"O tamanho diferencia o título, e a direção da seta orienta o percurso indicado pela placa.","explanation":"A escala relativa e a direção da seta são características observáveis. Elas sugerem hierarquia e orientação, mas não comprovam a reação de todos os visitantes.","hint":"Descreva a função sugerida pelos elementos e limite a conclusão ao que foi mostrado.","errorFocus":"OBSERVABLE_FUNCTIONS_NOT_CERTAINTY","misconceptions":{"A placa prova que visitantes sempre seguirão a seta.":["DESIGN_AS_GUARANTEE_OF_BEHAVIOR"]},"position":2},{"id":"v5-art-compare-compositions-lockin-01","purpose":"LOCK_IN","difficulty":"HARD","cognitiveProcess":"EVALUATE","contextFamily":"INTERPRETACAO_DA_COR","statement":"Uma pessoa diz que um cartaz azul “com certeza acalma qualquer público”. Qual evidência adicional ajudaria a avaliar essa afirmação?","options":["Confirmar apenas que o cartaz contém azul.","Supor que todas as pessoas associam cores do mesmo modo.","Investigar o contexto, a combinação dos elementos e como diferentes públicos interpretam o cartaz.","Descobrir o tamanho do papel, sem observar o uso ou o público."],"correctAnswer":"Investigar o contexto, a combinação dos elementos e como diferentes públicos interpretam o cartaz.","explanation":"Uma cor isolada não determina uma resposta universal. Contexto, combinação visual e interpretações de públicos diferentes ajudam a avaliar a afirmação.","hint":"Pergunte que evidências sustentariam uma afirmação sobre efeito e para quem.","errorFocus":"COLOR_MEANING_NEEDS_CONTEXT","misconceptions":{"Confirmar apenas que o cartaz contém azul.":["COLOR_AS_UNIVERSAL_EMOTION"]},"position":1},{"id":"v5-art-compare-compositions-review-01","purpose":"REVIEW","difficulty":"EASY","cognitiveProcess":"SYNTHESIZE","contextFamily":"LINHAS_CURVAS","statement":"Dois desenhos autorais usam linhas curvas. No primeiro, elas se aproximam de um ponto central; no segundo, acompanham horizontalmente a borda. Que comparação evita tratar a mesma forma como se tivesse sempre o mesmo efeito?","options":["Concluir que toda linha curva produz movimento idêntico.","Ignorar a posição porque os dois desenhos usam curvas.","Afirmar que um desenho é melhor sem definir critérios.","Relacionar a direção e a posição das linhas ao restante de cada composição."],"correctAnswer":"Relacionar a direção e a posição das linhas ao restante de cada composição.","explanation":"A forma das linhas é apenas parte da composição. Direção, posição e relação com outros elementos ajudam a explicar efeitos possíveis.","hint":"Compare a linha com sua posição e com os demais elementos em cada desenho.","errorFocus":"RELATION_TO_WHOLE","misconceptions":{"Concluir que toda linha curva produz movimento idêntico.":["ELEMENT_AS_FIXED_EFFECT"]},"position":1},{"id":"v11-art-compare-compositions-001","purpose":"PROBE","difficulty":"EASY","cognitiveProcess":"IDENTIFY","contextFamily":"V11_ART_COMPARE_CONTRAST_01","statement":"Os dois cartazes autorais da Feira de trocas do bairro usam o mesmo texto, mas o cartaz A coloca a chamada azul-marinho grande sobre um bloco amarelo, enquanto o B usa letras cinza-claro sobre fundo branco. Qual diferença de composição é observável?","options":["A separação entre chamada e fundo é mais forte no cartaz A, criando uma hierarquia mais nítida.","O cartaz B tem maior contraste porque todos os elementos têm peso semelhante.","Os cartazes são idênticos porque anunciam o mesmo evento.","O cartaz A prova que toda cor amarela comunica urgência."],"correctAnswer":"A separação entre chamada e fundo é mais forte no cartaz A, criando uma hierarquia mais nítida.","explanation":"A resposta se apoia nas relações visuais descritas e separa observação de interpretação. Compare contraste, escala e relação figura-fundo nos dois cartazes.","hint":"Observe elementos e relações antes de atribuir intenção, emoção ou significado universal.","errorFocus":"ART_VISUAL_EVIDENCE_BEFORE_INFERENCE","misconceptions":{"O cartaz B tem maior contraste porque todos os elementos têm peso semelhante.":["ART_VISUAL_EVIDENCE_BEFORE_INFERENCE"]},"visualStimulus":{"layout":"TWO_COLUMN","items":[{"src":"/learning/art/poster-contrast-a.svg","alt":"Cartaz A: chamada “Feira de trocas do bairro” em letras azul-marinho, grande, sobre um bloco amarelo; as informações de data e local aparecem menores abaixo.","caption":"Cartaz A"},{"src":"/learning/art/poster-contrast-b.svg","alt":"Cartaz B: a mesma chamada em letras cinza-claro diretamente sobre fundo branco; os detalhes têm tamanho e peso visual próximos aos da chamada.","caption":"Cartaz B"}]},"position":3},{"id":"v11-art-compare-compositions-002","purpose":"PROBE","difficulty":"EASY","cognitiveProcess":"DISTINGUISH","contextFamily":"V11_ART_COMPARE_CONTRAST_02","statement":"Os dois cartazes autorais da Feira de trocas do bairro usam o mesmo texto, mas o cartaz A coloca a chamada azul-marinho grande sobre um bloco amarelo, enquanto o B usa letras cinza-